import "lib/Counter.ems" as counters;
@counters::Counter #counter;
@UI.Column #root {
  @UI.Text #count { content <= counter.value as number; }
  @UI.Button #up { text: "Увеличить"; }
  @UI.Button #down { text: "Уменьшить"; }
}
up.clicked ~> counter.Change(delta: 1);
down.clicked ~> counter.Change(delta: -1);

import "Math.ems" as math;
export @Counter {
  value:Number=1;
  +Change(delta:Number)->Number graph {
    @self::value::read #read {}
    @math::Add #add { a <= #read; b <= input::delta; }
    @self::value::write #write { value <= #add; }
    @std::program::Result #result { value <= #write; }
    + #read;
    #read.next ~> #add.enter;
    #add.next ~> #write.enter;
    #write.next ~> #result.enter;
  }
  ? value>=0;
}

export @Add(a:Number,b:Number)->Number graph {
  @core::add #sum { a <= input::a; b <= input::b; }
  @std::program::Result #result { value <= #sum; }
  + #sum;
  #sum.next ~> #result.enter;
}
